@sealed
class TermSessionImpl extends RustOpaque implements TermSession {
  // Not to be used by end users
  TermSessionImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  TermSessionImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_TermSession,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_TermSession,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_TermSessionPtr,
  );

  /// Encode everything that changed since the previous call, on a worker
  /// thread. The result reaches Dart after the current frame has started,
  /// so it is painted one refresh later ("async" pipeline).
  Future<FrameBatch> encode() =>
      RustLib.instance.api.crateApiTermTermSessionEncode(that: this);

  /// Same as [`encode`](Self::encode) but on the calling (UI) thread, so a
  /// frame can encode, record and paint within one refresh ("sync"
  /// pipeline). Encoding takes tens of microseconds.
  FrameBatch encodeNow() =>
      RustLib.instance.api.crateApiTermTermSessionEncodeNow(that: this);

  /// Feed bytes directly (keyboard echo tests, pasted text).
  Future<void> feed({required List<int> data}) =>
      RustLib.instance.api.crateApiTermTermSessionFeed(that: this, data: data);

  Future<void> resize({required int cols, required int rows}) => RustLib
      .instance
      .api
      .crateApiTermTermSessionResize(that: this, cols: cols, rows: rows);

  String screenText() =>
      RustLib.instance.api.crateApiTermTermSessionScreenText(that: this);

  Future<void> scroll({required int deltaLines}) => RustLib.instance.api
      .crateApiTermTermSessionScroll(that: this, deltaLines: deltaLines);

  /// Feed `workload` from a background thread at `mib_per_sec` (0 = as
  /// fast as possible) until `total_mib` have been fed or
  /// [`stop_workload`](Self::stop_workload) is called.
  Future<void> startWorkload({
    required String workload,
    required int cols,
    required int rows,
    required double mibPerSec,
    required double totalMib,
  }) => RustLib.instance.api.crateApiTermTermSessionStartWorkload(
    that: this,
    workload: workload,
    cols: cols,
    rows: rows,
    mibPerSec: mibPerSec,
    totalMib: totalMib,
  );

  void stopWorkload() =>
      RustLib.instance.api.crateApiTermTermSessionStopWorkload(that: this);
}
